#!/usr/bin/env bash
# Q-E1 500-episode expansion, generated by q_expand_plan.py from out/expand_plan.json.
# Same GPU 1 settings. One process per (checkpoint, family, mode); N = cells x 500.
set -u
cd "$(dirname "$0")"
PY=C:/Users/AI-WS01/anaconda3/envs/isaac311-moects/python.exe
RUN=C:/isaac/ext/go2_rl_robotlab/logs/rsl_rl/go2_moe_cts/2026-10-10_12-47-48_e1_seed42_n8192
export CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=1 OMNI_KIT_ACCEPT_EULA=YES PYTHONUNBUFFERED=1
one() {
  local tag=$1; shift
  if [ -f "out/$tag/cells.json" ]; then echo "RUN $tag SKIP"; return; fi
  local t0=$(date +%s)
  "$PY" q_eval.py --headless --tag "$tag" "$@" > "out/$tag.log" 2>&1
  echo "RUN $tag EXIT $? $(( $(date +%s) - t0 ))s $(nvidia-smi --query-gpu=index,memory.used --format=csv,noheader | tr '\n' ' ')"
}
one x500_m20000_flat --policy student --checkpoint "$RUN/model_20000.pt" --families flat --cells fwd02,stop03 --episodes 500
one x500_m20000_wave --policy student --checkpoint "$RUN/model_20000.pt" --families wave --cells back03,fwd02,fwd05,right03 --episodes 500
one x500_m20000_slope_up --policy student --checkpoint "$RUN/model_20000.pt" --families slope_up --cells stop03 --episodes 500
one x500_m20000_slope_down --policy student --checkpoint "$RUN/model_20000.pt" --families slope_down --cells stop03 --episodes 500
one x500_m20000_rough_slope --policy student --checkpoint "$RUN/model_20000.pt" --families rough_slope --cells fwd02,right03,stop03 --episodes 500
one x500_m20000_stairs_up --policy student --checkpoint "$RUN/model_20000.pt" --families stairs_up --cells left03 --episodes 500
one x500_m20000_stairs_down --policy student --checkpoint "$RUN/model_20000.pt" --families stairs_down --cells stop03 --episodes 500
one x500_m20000_obstacles --policy student --checkpoint "$RUN/model_20000.pt" --families obstacles --cells back03,fwd02,fwd03,fwd05,left03,right03,stop03 --episodes 500
one x500_m20000_offplat_stairs_up --policy student --checkpoint "$RUN/model_20000.pt" --families stairs_up --cells yawR05 --episodes 500 --spawn_offset stand=2.5,yaw=2.5,stop=1.75
one x500_m20000_offplat_stairs_down --policy student --checkpoint "$RUN/model_20000.pt" --families stairs_down --cells yawR05 --episodes 500 --spawn_offset stand=2.5,yaw=2.5,stop=1.75
one x500_m20000_offplat_obstacles --policy student --checkpoint "$RUN/model_20000.pt" --families obstacles --cells yawL05 --episodes 500 --spawn_offset stand=2.5,yaw=2.5,stop=1.75
one x500_m20499_flat --policy student --checkpoint "$RUN/model_20499.pt" --families flat --cells fwd02,stop03 --episodes 500
one x500_m20499_wave --policy student --checkpoint "$RUN/model_20499.pt" --families wave --cells back03,fwd02,fwd05,right03 --episodes 500
one x500_m20499_slope_up --policy student --checkpoint "$RUN/model_20499.pt" --families slope_up --cells stop03 --episodes 500
one x500_m20499_slope_down --policy student --checkpoint "$RUN/model_20499.pt" --families slope_down --cells stop03 --episodes 500
one x500_m20499_rough_slope --policy student --checkpoint "$RUN/model_20499.pt" --families rough_slope --cells fwd02,right03,stop03 --episodes 500
one x500_m20499_stairs_up --policy student --checkpoint "$RUN/model_20499.pt" --families stairs_up --cells left03 --episodes 500
one x500_m20499_stairs_down --policy student --checkpoint "$RUN/model_20499.pt" --families stairs_down --cells stop03 --episodes 500
one x500_m20499_obstacles --policy student --checkpoint "$RUN/model_20499.pt" --families obstacles --cells back03,fwd02,fwd03,fwd05,left03,right03,stop03 --episodes 500
one x500_m20499_offplat_stairs_up --policy student --checkpoint "$RUN/model_20499.pt" --families stairs_up --cells yawR05 --episodes 500 --spawn_offset stand=2.5,yaw=2.5,stop=1.75
one x500_m20499_offplat_stairs_down --policy student --checkpoint "$RUN/model_20499.pt" --families stairs_down --cells yawR05 --episodes 500 --spawn_offset stand=2.5,yaw=2.5,stop=1.75
one x500_m20499_offplat_obstacles --policy student --checkpoint "$RUN/model_20499.pt" --families obstacles --cells yawL05 --episodes 500 --spawn_offset stand=2.5,yaw=2.5,stop=1.75
echo "EXPAND DONE"
